زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "demand_forecast",
      "description": "پیش‌بینی و فروش واقعی هر دسته و هفته",
      "dimensions": [
        "category",
        "week"
      ],
      "measures": [
        "forecast_units",
        "actual_units"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "forecast_accuracy",
      "description": "دقت پیش‌بینی تقاضا",
      "formula": "یک منهای قدرمطلق خطا تقسیم بر واقعی",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "سقف پوشش موجودی دسته‌های فاسدشدنی هفت روز",
    "انقضا با آستانهٔ هشدار سی روز پایش می‌شود",
    "زنجیرهٔ ۱۲۰ فروشگاه با مرکز توزیع متمرکز و انبار شعبه"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "forecast_accuracy"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "forecast_accuracy_pct": {
    "prev": 90.8,
    "curr": 84.1,
    "change_pp": -6.7
  },
  "category": "نان و نیم‌فروشی"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "demand_forecast",
    "filters": {
      "category": "نان و نیم‌فروشی",
      "period": "curr_month"
    }
  }
}

