«لبنیات» و «نان و نیم‌فروشی» را از نظر سرمایه در گردش مقایسه کن. (مدیر موجودی — یاس فروشگاه‌ها)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "stock_levels",
      "description": "موجودی به تفکیک دستهٔ کالا و شعبه",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_cover",
      "description": "پوشش موجودی",
      "formula": "موجودی تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "stock_turnover",
      "description": "گردش موجودی",
      "formula": "فروش دوره تقسیم بر میانگین موجودی",
      "unit": "بار",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "انقضا با آستانهٔ هشدار سی روز پایش می‌شود",
    "سفارش‌گذاری روزانه از مرکز توزیع",
    "زنجیرهٔ ۱۲۰ فروشگاه با مرکز توزیع متمرکز و انبار شعبه"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "stock_levels",
    "filters": {
      "category": [
        "لبنیات",
        "نان و نیم‌فروشی"
      ],
      "period": "today"
    }
  }
}

